 function beginImport(matrix){if(!matrix.length)return;setModal({...modal,kind:'import',matrix});}
 function applyImport(incoming){if(current.current.busy)throw Error('正在保存，请稍后再导入');const target=modal.target,projectId=modal.projectId;const test=structuredClone(current.current.data);const destination=target==='materials'?test.materials:ledgerBook(test.projects.find(p=>p.id===projectId),target,modal.worksheetId||'');destination.rows.push(...incoming);validate(test);edit(d=>{const dest=target==='materials'?d.materials:ledgerBook(d.projects.find(p=>p.id===projectId),target,modal.worksheetId||'');dest.rows.push(...incoming);});setModal(null);setMessage(`已加入 ${incoming.length} 行 · 可撤销，请保存`);}
 async function importSheet(e){try{const file=e.target.files[0];if(!file)return;if(file.size>MAX_IMPORT_BYTES)throw Error(`导入表格不得超过 ${MAX_IMPORT_BYTES/1000000} MB`);const ext=file.name.toLowerCase().split('.').pop();let sheets;if(ext==='csv'||ext==='tsv')sheets=[{name:file.name,matrix:parseDelimited(await file.text(),ext==='csv'?',' : '\t')}];else if(ext==='xlsx'||ext==='xls')sheets=await importExcelWorkbook(await file.arrayBuffer(),ext);else throw Error('暂仅支持 .xlsx、.xls、.csv、.tsv');if(!sheets?.length)throw Error('工作簿没有可读取的工作表');setModal({kind:'sheet',sheets,names:sheets.map(s=>s.name),name:sheets[0].name,source:file.name,target:page==='materials'?'materials':ledgerKey,worksheetId:activeBusinessWorksheet,projectId:rootProject.id});}catch(e){setMessage('读取表格失败：'+e.message);}e.target.value='';}
 function locate(row){if(!rootProject.model){setMessage('此项目尚未配置模型，记录仍保留在台账。');return;}const point=locateReceipt(row,rootProject.modelConfig);if(!point.building){setMessage('部位未能匹配唯一楼栋和有效楼层。请核对标段、楼栋及楼层（如 11栋 / 2F）。');return;}setModelRecord(ledgerKey+':'+activeBusinessWorksheet+':'+row.id);setPage('overview');setSelected(null);setMessage('已定位模型 · 高亮显示对应楼栋或楼层');}
 async function browseReferences(path){try{const listing=await rpc('reference-list',{path});setModal(m=>m&&['reference','relink'].includes(m.kind)?{...m,listing,error:''}:m);}catch(e){setModal(m=>m&&['reference','relink'].includes(m.kind)?{...m,error:e.message}:m);}}
