 async function addReference(){const requestId=uid(),request={...modal,pending:true,requestId};if(modal.pending)return;setModal(request);try{const file=await rpc('reference',{path:request.path.trim()});if(liveModal.current?.requestId!==requestId)return;const id=uid();const applied=edit(d=>{if(request.kind==='relink'){Object.assign(d.files.find(x=>x.id===request.file.id),file);return;}d.files.push({...file,id,projectId:project.id,createdAt:new Date().toISOString()});if(request.rowId)book(d).rows.find(r=>r.id===request.rowId)?.files.push(id);});if(applied===false)throw Error('正在保存，请稍后重新添加');setModal(null);setMessage('文件引用已更新，未复制内容；请保存更改。');}catch(e){setModal(m=>m?.requestId===requestId?{...m,pending:false,error:e.message}:m);}}

