  exportLock.current=true;setExporting(true);setMessage(`正在生成 ${chosen.length} 条记录的 Excel…`);
  try{const title=materials?'材料价格库':ledgerTitle,base64=await exportLedgerExcel({rows:chosen.map(({id,cells,notes,source})=>({id,cells,notes,source})),columns:materials?data.materials.columns:cols,format:(materials?data.materials:book(data)).format,kind:materials?'materials':ledgerKey,title,projectName:materials?'个人材料价格库':project.name,scope:selectedOnly?'勾选记录':'当前筛选结果'});const path=await rpc('export',{name:(materials?'个人材料价格库':project.name+'-'+ledgerTitle)+'.xlsx',base64});setMessage(`已导出 ${chosen.length} 条记录到 `+path);}catch(e){setMessage('导出失败：'+e.message);}finally{exportLock.current=false;setExporting(false);}
